//! THIRD-PARTY-LICENSES.md and Cargo.lock agree.
//!
//! The file is generated by `scripts/third-party-licenses.sh` (it needs `cargo-about`). This test
//! needs no tool: every crate of `Cargo.lock` must be named in the file, either in the list of
//! crates that a release build contains or in the closing list of crates that it does not, with
//! the same version. A dependency update that does not regenerate the file fails here.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    reason = "a test fails by panic"
)]

use std::collections::BTreeSet;
use std::path::Path;

const REGENERATE: &str = "run scripts/third-party-licenses.sh and commit THIRD-PARTY-LICENSES.md";

/// `name version` of every package in a `Cargo.lock` that comes from a registry. The crates of
/// this workspace (`crewboard` and the crates under `crates/`) have no `source`: their version
/// changes with every release, and they are not third-party code.
fn lock_crates(lock: &str) -> BTreeSet<String> {
    let value: toml::Table = lock.parse().expect("Cargo.lock is TOML");
    value["package"]
        .as_array()
        .expect("package list")
        .iter()
        .filter(|p| p.get("source").is_some())
        .map(|p| {
            format!(
                "{} {}",
                p["name"].as_str().unwrap(),
                p["version"].as_str().unwrap()
            )
        })
        .collect()
}

/// The crates of the file: (shipped, not shipped), each as `name version`.
fn listed_crates(file: &str) -> (BTreeSet<String>, BTreeSet<String>) {
    let mut shipped = BTreeSet::new();
    let mut other = BTreeSet::new();
    let mut section = "";
    let mut in_fence = false;
    for line in file.lines() {
        if line.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        if in_fence {
            continue;
        }
        if let Some(h) = line.strip_prefix("## ") {
            section = if h.starts_with("Crates and license texts") {
                "shipped"
            } else if h.starts_with("Not part of a release build") {
                "other"
            } else {
                ""
            };
            continue;
        }
        let Some(item) = line.strip_prefix("- ") else {
            continue;
        };
        let mut words = item.split(' ');
        let (Some(name), Some(version)) = (words.next(), words.next()) else {
            continue;
        };
        let key = format!("{name} {version}");
        match section {
            "shipped" => {
                shipped.insert(key);
            }
            "other" if item.ends_with("(not shipped)") => {
                other.insert(key);
            }
            _ => {}
        }
    }
    (shipped, other)
}

/// Problems between a lock text and a license file text; empty when they agree.
fn problems(lock: &str, file: &str) -> Vec<String> {
    let want = lock_crates(lock);
    let (shipped, other) = listed_crates(file);
    let mut out = Vec::new();
    for c in &want {
        if !shipped.contains(c) && !other.contains(c) {
            out.push(format!("in Cargo.lock, not in the file: {c}"));
        }
    }
    for c in shipped.union(&other) {
        if !want.contains(c) {
            out.push(format!("in the file, not in Cargo.lock: {c}"));
        }
    }
    for c in shipped.intersection(&other) {
        out.push(format!("in both lists: {c}"));
    }
    out
}

fn read(name: &str) -> String {
    std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join(name)).unwrap()
}

#[test]
fn every_crate_of_cargo_lock_is_in_the_license_file() {
    let p = problems(&read("Cargo.lock"), &read("THIRD-PARTY-LICENSES.md"));
    assert!(p.is_empty(), "{REGENERATE}:\n{}", p.join("\n"));
}

#[test]
fn the_license_file_names_the_direct_dependencies_and_the_c_code_notices() {
    let file = read("THIRD-PARTY-LICENSES.md");
    let (shipped, _) = listed_crates(&file);
    let names: BTreeSet<&str> = shipped.iter().filter_map(|c| c.split(' ').next()).collect();
    for dep in direct_dependencies() {
        assert!(
            names.contains(dep.as_str()),
            "direct dependency {dep}: {REGENERATE}"
        );
    }
    // The C code of aws-lc-sys and the Unicode data need their own notices.
    for needle in [
        "### aws-lc-sys: LICENSE",
        "Amazon.com, Inc. or its affiliates",
        "Eric Young",
        "fiat-crypto authors",
        "Unicode License v3",
        "isis agora lovecruft",
    ] {
        assert!(file.contains(needle), "missing {needle:?}: {REGENERATE}");
    }
    // The generic BSD text without a copyright line means that a license file was not found.
    // For aws-lc-sys it is expected: its copyright lines are in the complete files at the end.
    let generic = "Copyright (c) <year> <owner>";
    if let Some(at) = file.find(generic) {
        let head = &file[..at];
        let section = &head[head.rfind("\n### ").unwrap()..];
        let users: Vec<&str> = section.lines().filter(|l| l.starts_with("- ")).collect();
        assert!(
            users.iter().all(|u| u.starts_with("- aws-lc-sys ")),
            "a crate has only the generic BSD text, see about.toml: {users:?}"
        );
    }
}

/// The workspace members: the root package and the paths of `[workspace] members`.
fn members() -> Vec<String> {
    let manifest: toml::Table = read("Cargo.toml").parse().unwrap();
    manifest["workspace"]["members"]
        .as_array()
        .unwrap()
        .iter()
        .map(|m| m.as_str().unwrap().to_string())
        .collect()
}

/// The `[dependencies]` of every workspace member (the shipped code), without the workspace
/// crates themselves.
fn direct_dependencies() -> BTreeSet<String> {
    let manifests: Vec<toml::Table> = members()
        .iter()
        .map(|m| read(&format!("{m}/Cargo.toml")).parse().unwrap())
        .collect();
    let own: BTreeSet<&str> = manifests
        .iter()
        .map(|m| m["package"]["name"].as_str().unwrap())
        .collect();
    manifests
        .iter()
        .filter_map(|m| m.get("dependencies").and_then(|d| d.as_table()))
        .flat_map(|d| d.keys().cloned())
        .filter(|d| !own.contains(d.as_str()))
        .collect()
}

#[test]
fn the_direct_dependencies_come_from_every_member_and_skip_the_workspace_crates() {
    assert!(members().contains(&".".to_string()), "{:?}", members());
    let deps = direct_dependencies();
    // The root alone has 11 direct dependencies; a scan that reads no manifest finds none.
    assert!(deps.len() >= 11, "{deps:?}");
    for d in ["clap", "reqwest", "ssh-key"] {
        assert!(deps.contains(d), "{d} missing in {deps:?}");
    }
    assert!(
        !deps
            .iter()
            .any(|d| d.starts_with("crewboard") || d == "host-lock"),
        "{deps:?}"
    );
}

#[test]
fn the_check_fires_on_a_stale_file_and_passes_a_matching_one() {
    // `crewboard` and `crewboard-x` are workspace crates (no `source`), `a` and `b` come from a
    // registry.
    let reg = "source = \"registry+https://github.com/rust-lang/crates.io-index\"\n";
    let lock = format!(
        "[[package]]\nname = \"crewboard\"\nversion = \"1.0.0\"\n\n\
         [[package]]\nname = \"crewboard-x\"\nversion = \"1.0.0\"\n\n\
         [[package]]\nname = \"a\"\nversion = \"1.0.0\"\n{reg}\n\
         [[package]]\nname = \"b\"\nversion = \"2.0.0\"\n{reg}"
    );
    let lock = lock.as_str();
    let file = "## Crates and license texts\n\n- a 1.0.0 (https://x)\n\n```text\n- zzz 9.9.9\n```\n\n\
                ## Not part of a release build\n\n- b 2.0.0 (not shipped)\n";
    assert_eq!(problems(lock, file), Vec::<String>::new());
    // A crate that is missing, a version that changed, a crate that Cargo.lock does not have.
    let missing = file.replace("- a 1.0.0 (https://x)\n", "");
    assert_eq!(
        problems(lock, &missing),
        vec!["in Cargo.lock, not in the file: a 1.0.0"]
    );
    let bumped = lock.replace("2.0.0", "2.0.1");
    let p = problems(&bumped, file);
    assert_eq!(p.len(), 2, "{p:?}");
    assert!(p.iter().any(|l| l.contains("b 2.0.1")) && p.iter().any(|l| l.contains("b 2.0.0")));
}
